+	timestamp = ((guint64)rec->ts.secs - (guint64)netxray->start_secs)*1000000
 		+ ((guint64)rec->ts.nsecs)/1000;
 	t32 = (guint32)(timestamp%G_GINT64_CONSTANT(4294967296));
 	rec_hdr.timelo = GUINT32_TO_LE(t32);
